import java.util.*;

public class Main {
    void squarePattern(int n) {
        for (int i = 0; i < n; i++) {              // one iteration per row
            for (int j = 0; j < n; j++) {           // one iteration per column
                System.out.print("*");                // print a single star, one call per character
            }
            System.out.println();                  // move to the next line after the row
        }
    }

    public static void main(String[] args) {
        Main solution = new Main();
        solution.squarePattern(3);
    }
}

