import java.util.*;

public class Main {
    void squarePattern(int n) {
        String row = "*".repeat(n);                // build one full row of stars in a single operation
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            sb.append(row);
            if (i < n - 1) {
                sb.append('\n');
            }
        }
        System.out.println(sb);                    // a single call outputs the entire pattern at once
    }

    public static void main(String[] args) {
        Main solution = new Main();
        solution.squarePattern(3);
    }
}

